// daysAgo — format "X hari lalu"
func daysAgo(t time.Time) string {
	d := time.Since(t)
	days := int(d.Hours() / 24)
	if days > 0 {
		if days == 1 {
			return "1 hari lalu"
		}
		return fmt.Sprintf("%d hari lalu", days)
	}
	hours := int(d.Hours())
	if hours > 0 {
		if hours == 1 {
			return "1 jam lalu"
		}
		return fmt.Sprintf("%d jam lalu", hours)
	}
	return "baru saja"
}

